query:
SELECT ?item ?itemLabel (GROUP_CONCAT(DISTINCT ?alt; separator="|") AS ?aliases) (GROUP_CONCAT(DISTINCT ?countryLabel; separator="|") AS ?countries) WHERE {
  ?item wdt:P31/wdt:P279* wd:Q39367.
  OPTIONAL { ?item skos:altLabel ?alt FILTER(LANG(?alt)="en") }
  OPTIONAL { ?item wdt:P495 ?country. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". ?item rdfs:label ?itemLabel. ?country rdfs:label ?countryLabel. }
} GROUP BY ?item ?itemLabel
